    {
      "policy_source_id": "q11",
      "interpretation": "The agent must not add checked bags that the user does not need (i.e., beyond free allowances).",
      "modality": "FORBID"
    },
    {
      "policy_source_id": "q12",
      "interpretation": "For gold members, 3 free checked bags are allowed for economy passengers.",
      "modality": "PERMIT"
    },
    {
      "policy_source_id": "q11",
      "interpretation": "The agent must not make tool calls simultaneously with user communication.",
      "modality": "FORBID"
    }
  ],
